sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || newValue == '') {
        return;
    }

    switch (newValue) {

        case "water_leakage":
            g_form.setValue("priority", "high");
            break;

        case "road_damage":
            g_form.setValue("priority", "high");
            break;

        case "street_light":
            g_form.setValue("priority", "medium");
            break;

        case "electricity":
            g_form.setValue("priority", "critical");
            break;

        case "drainage":
            g_form.setValue("priority", "high");
            break;

        case "garbage":
            g_form.setValue("priority", "medium");
            break;

        case "public_park":
            g_form.setValue("priority", "low");
            break;
    }
}
